export default async function handler(req, res) {
  if (req.method !== "POST") {
    return res.status(405).json({ error: "Method not allowed" });
  }

  const { syllable, meaning } = req.body;

  // 뜻으로 찾기
  if (meaning) {
    const keyword = meaning.trim();
    const results = [];
    const seen = new Set();
    for (const [sound, list] of Object.entries(HANJA_DB)) {
      for (const h of list) {
        if (h.meaning.includes(keyword) && !seen.has(h.char)) {
          seen.add(h.char);
          const code = h.char.codePointAt(0);
          if (code >= 0x4E00 && code <= 0x9FFF) {
            results.push({ ...h, reading: sound });
          }          if (results.length >= 30) break;
        }
      }
      if (results.length >= 30) break;
    }
    return res.status(200).json({ hanja: results });
  }

  // 음으로 찾기 (기존)
  if (!syllable) return res.status(400).json({ error: "음절을 입력해주세요." });
  const key = syllable.trim();
  const hanja = HANJA_DB[key] || [];
  const seen = new Set();
  const unique = hanja.filter(h => {
    if (seen.has(h.char)) return false;
    seen.add(h.char);
    return true;
  });
const filtered = unique.filter(h => {
    const code = h.char.codePointAt(0);
    return code >= 0x4E00 && code <= 0x9FFF;
  });
  if (filtered.length > 0) {
    return res.status(200).json({
      syllable: key,
      hanja: filtered.map(h => ({ ...h, reading: key })),
    });
  }
  // AI fallback
  const prompt = `한국어 음절 "${key}"의 음(소리)을 가진 한자들을 이름에 자주 쓰이는 것 위주로 10개 찾아줘. 중복 없이 서로 다른 한자 10개.
반드시 아래 JSON 형식으로만 응답해. 설명, 마크다운, 백틱 없이 순수 JSON만:
{
  "syllable": "${key}",
  "hanja": [
    {
      "char": "金",
      "meaning": "쇠 금, 성 김",
      "reading": "${key}"
    }
  ]
}
규칙:
- char는 중복 없이 서로 다른 한자만
- meaning은 "훈(뜻) 음(소리)" 형식. 예: "쇠 금" / "강 하" / "볼 람"
- reading은 반드시 "${key}"로 고정`;
  try {
    const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${process.env.GROQ_API_KEY}`,
      },
      body: JSON.stringify({
        model: "llama-3.3-70b-versatile",
        messages: [{ role: "user", content: prompt }],
        temperature: 0.1,
        max_tokens: 800,
      }),
    });
    const data = await response.json();
    const text = data.choices?.[0]?.message?.content || "";
    const clean = text.replace(/```json|```/g, "").trim();
    const parsed = JSON.parse(clean);
    const seen2 = new Set();
    parsed.hanja = (parsed.hanja || []).filter(h => {
      if (seen2.has(h.char)) return false;
      seen2.add(h.char);
      return true;
    });
    return res.status(200).json(parsed);
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: "한자 조회 중 오류가 발생했어요." });
  }
}